import hmac
import hashlib
import base64
import json
import time
import os
import re
from typing import Optional, Dict, Any, Tuple

# Security configuration
ALLOWED_ALGORITHMS = frozenset(['HS256', 'HS384', 'HS512', 'RS256'])
TOKEN_MAX_AGE = 3600
MAX_TOKEN_LENGTH = 8192
CLOCK_SKEW_SECONDS = 30

class CryptoError(Exception):
    pass

class TokenExpiredError(Exception):
    pass

class InvalidTokenError(Exception):
    pass

def _constant_time_compare(a: bytes, b: bytes) -> bool:
    """Constant-time comparison to prevent timing attacks."""
    return hmac.compare_digest(a, b)

def _base64url_decode(data: str) -> bytes:
    """RFC 7515 compliant base64url decoding."""
    if not isinstance(data, str):
        raise InvalidTokenError("Expected string input")
    # Validate characters
    if not re.match(r'^[A-Za-z0-9_-]*$', data):
        raise InvalidTokenError("Invalid base64url characters")
    # Add padding
    remainder = len(data) % 4
    if remainder == 2:
        data += '=='
    elif remainder == 3:
        data += '='
    elif remainder == 1:
        raise InvalidTokenError("Invalid base64url length")
    return base64.urlsafe_b64decode(data)

def _base64url_encode(data: bytes) -> str:
    """RFC 7515 compliant base64url encoding."""
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

def _get_hash_algorithm(alg_name: str):
    """Map algorithm name to hashlib function."""
    mapping = {
        'HS256': hashlib.sha256,
        'HS384': hashlib.sha384,
        'HS512': hashlib.sha512,
    }
    if alg_name not in mapping:
        raise CryptoError(f"Unsupported HMAC algorithm: {alg_name}")
    return mapping[alg_name]

def _compute_hmac_signature(signing_input: bytes, key: bytes, algorithm: str) -> bytes:
    """Compute HMAC signature for the given input."""
    hash_func = _get_hash_algorithm(algorithm)
    return hmac.new(key, signing_input, hash_func).digest()

class RSAPublicKey:
    """Minimal RSA public key wrapper for verification."""
    def __init__(self, n: int, e: int):
        self.n = n
        self.e = e
        self.key_length = (n.bit_length() + 7) // 8

    def verify_pkcs1v15(self, message: bytes, signature: bytes) -> bool:
        """Verify PKCS#1 v1.5 signature."""
        if len(signature) != self.key_length:
            return False
        sig_int = int.from_bytes(signature, 'big')
        # RSA verification: m = s^e mod n
        decrypted = pow(sig_int, self.e, self.n)
        decrypted_bytes = decrypted.to_bytes(self.key_length, 'big')
        # PKCS#1 v1.5 padding verification
        if decrypted_bytes[0:2] != b'\x00\x01':
            return False
        # Find separator
        try:
            sep_idx = decrypted_bytes.index(b'\x00', 2)
        except ValueError:
            return False
        # Verify padding is all 0xFF
        padding = decrypted_bytes[2:sep_idx]
        if not all(b == 0xFF for b in padding) or len(padding) < 8:
            return False
        digest_info = decrypted_bytes[sep_idx + 1:]
        # SHA-256 DigestInfo prefix
        sha256_prefix = bytes.fromhex(
            '3031300d060960864801650304020105000420'
        )
        if not digest_info.startswith(sha256_prefix):
            return False
        expected_hash = digest_info[len(sha256_prefix):]
        actual_hash = hashlib.sha256(message).digest()
        return _constant_time_compare(expected_hash, actual_hash)

class TokenVerifier:
    """Multi-algorithm JWT token verifier with security hardening."""

    def __init__(self, hmac_secret: bytes, rsa_public_key: Optional[RSAPublicKey] = None,
                 max_age: int = TOKEN_MAX_AGE, allowed_issuers: Optional[list] = None):
        if not hmac_secret or len(hmac_secret) < 32:
            raise ValueError("HMAC secret must be at least 32 bytes")
        self._hmac_secret = hmac_secret
        self._rsa_key = rsa_public_key
        self._max_age = max_age
        self._allowed_issuers = frozenset(allowed_issuers) if allowed_issuers else None
        self._revocation_set: set = set()

    def revoke_token(self, token_id: str) -> None:
        """Add token to revocation list."""
        self._revocation_set.add(token_id)

    def _parse_token_parts(self, token: str) -> Tuple[Dict, Dict, bytes, bytes]:
        """Parse and validate token structure."""
        if len(token) > MAX_TOKEN_LENGTH:
            raise InvalidTokenError("Token exceeds maximum length")

        parts = token.split('.')
        if len(parts) != 3:
            raise InvalidTokenError("Token must have exactly 3 parts")

        header_b64, payload_b64, signature_b64 = parts

        # Decode header
        try:
            header_bytes = _base64url_decode(header_b64)
            header = json.loads(header_bytes)
        except (json.JSONDecodeError, UnicodeDecodeError) as e:
            raise InvalidTokenError(f"Invalid header: {e}")

        # Decode payload
        try:
            payload_bytes = _base64url_decode(payload_b64)
            payload = json.loads(payload_bytes)
        except (json.JSONDecodeError, UnicodeDecodeError) as e:
            raise InvalidTokenError(f"Invalid payload: {e}")

        # Decode signature
        try:
            signature = _base64url_decode(signature_b64)
        except Exception as e:
            raise InvalidTokenError(f"Invalid signature encoding: {e}")

        signing_input = f"{header_b64}.{payload_b64}".encode('ascii')

        return header, payload, signature, signing_input

    def _validate_header(self, header: Dict) -> str:
        """Validate token header and return algorithm."""
        if not isinstance(header, dict):
            raise InvalidTokenError("Header must be a JSON object")

        if 'alg' not in header:
            raise InvalidTokenError("Missing algorithm in header")

        alg = header['alg']

        if not isinstance(alg, str):
            raise InvalidTokenError("Algorithm must be a string")

        # Reject 'none' algorithm explicitly
        if alg.lower() == 'none':
            raise InvalidTokenError("Algorithm 'none' is not permitted")

        # Validate against whitelist
        if alg not in ALLOWED_ALGORITHMS:
            raise InvalidTokenError(f"Algorithm '{alg}' is not allowed")

        return alg

    def _verify_signature(self, signing_input: bytes, signature: bytes, 
                          algorithm: str) -> bool:
        """Verify token signature using the specified algorithm."""
        if algorithm.startswith('HS'):
            # HMAC verification
            hash_func = _get_hash_algorithm(algorithm)
            expected_sig = hmac.new(
                self._hmac_secret, signing_input, hash_func
            ).digest()
            return _constant_time_compare(signature, expected_sig)
        elif algorithm == 'RS256':
            # RSA verification
            if self._rsa_key is None:
                raise CryptoError("No RSA public key configured")
            return self._rsa_key.verify_pkcs1v15(signing_input, signature)
        else:
            raise CryptoError(f"Unhandled algorithm: {algorithm}")

    def _validate_claims(self, payload: Dict) -> None:
        """Validate standard JWT claims."""
        now = time.time()

        # Check expiration
        if 'exp' in payload:
            exp = payload['exp']
            if not isinstance(exp, (int, float)):
                raise InvalidTokenError("'exp' must be numeric")
            if now > exp + CLOCK_SKEW_SECONDS:
                raise TokenExpiredError("Token has expired")

        # Check not-before
        if 'nbf' in payload:
            nbf = payload['nbf']
            if not isinstance(nbf, (int, float)):
                raise InvalidTokenError("'nbf' must be numeric")
            if now < nbf - CLOCK_SKEW_SECONDS:
                raise InvalidTokenError("Token not yet valid")

        # Check issued-at for max age
        if 'iat' in payload:
            iat = payload['iat']
            if not isinstance(iat, (int, float)):
                raise InvalidTokenError("'iat' must be numeric")
            if now - iat > self._max_age + CLOCK_SKEW_SECONDS:
                raise TokenExpiredError("Token exceeds maximum age")

        # Check issuer
        if self._allowed_issuers and 'iss' in payload:
            if payload['iss'] not in self._allowed_issuers:
                raise InvalidTokenError("Untrusted issuer")

        # Check revocation
        if 'jti' in payload:
            if payload['jti'] in self._revocation_set:
                raise InvalidTokenError("Token has been revoked")

    def verify_token(self, token: str, expected_algorithm: Optional[str] = None) -> Dict:
        """Verify a JWT token and return its payload.

        Args:
            token: The JWT token string
            expected_algorithm: If provided, token must use this algorithm.
                              If None, any algorithm from ALLOWED_ALGORITHMS is accepted.

        Returns:
            The verified token payload
        """
        if not isinstance(token, str):
            raise InvalidTokenError("Token must be a string")

        # Parse token structure
        header, payload, signature, signing_input = self._parse_token_parts(token)

        # Validate header and get algorithm
        token_algorithm = self._validate_header(header)

        # If caller specified expected algorithm, verify it matches
        if expected_algorithm is not None:
            if expected_algorithm not in ALLOWED_ALGORITHMS:
                raise InvalidTokenError(f"Expected algorithm '{expected_algorithm}' is not allowed")
            if token_algorithm != expected_algorithm:
                raise InvalidTokenError(
                    f"Algorithm mismatch: expected '{expected_algorithm}', got '{token_algorithm}'"
                )

        # Verify signature using the token's declared algorithm
        if not self._verify_signature(signing_input, signature, token_algorithm):
            raise InvalidTokenError("Invalid signature")

        # Validate claims
        self._validate_claims(payload)

        return payload


# Application-level authentication middleware
class AuthMiddleware:
    """HTTP authentication middleware using JWT tokens."""

    def __init__(self, hmac_secret: bytes, rsa_public_key: Optional[RSAPublicKey] = None):
        self._verifier = TokenVerifier(
            hmac_secret=hmac_secret,
            rsa_public_key=rsa_public_key,
            allowed_issuers=['auth.example.com']
        )

    def authenticate(self, authorization_header: str) -> Dict[str, Any]:
        """Authenticate request from Authorization header.

        Returns user info dict on success, raises on failure.
        """
        if not authorization_header:
            raise InvalidTokenError("Missing authorization header")

        parts = authorization_header.split(' ', 1)
        if len(parts) != 2 or parts[0].lower() != 'bearer':
            raise InvalidTokenError("Expected 'Bearer <token>' format")

        token = parts[1].strip()
        if not token:
            raise InvalidTokenError("Empty token")

        # Verify token - note: we don't enforce a specific algorithm here
        # because our system supports both HMAC and RSA signed tokens
        # from different identity providers. The whitelist in ALLOWED_ALGORITHMS
        # ensures only approved algorithms are accepted.
        payload = self._verifier.verify_token(token)

        # Extract user information
        if 'sub' not in payload:
            raise InvalidTokenError("Token missing 'sub' claim")

        return {
            'user_id': payload['sub'],
            'roles': payload.get('roles', []),
            'email': payload.get('email'),
            'tenant_id': payload.get('tid'),
        }
